use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use jsonwebtoken::{decode, encode, Algorithm, DecodingKey, EncodingKey, Header, Validation};
use serde::{Deserialize, Serialize};
use std::fs;

#[derive(Debug, Serialize, Deserialize, Clone)]
struct Claims {
    sub: String,
    role: String,
    exp: usize,
}

struct AppState {
    rsa_public_key: Vec<u8>,
    rsa_private_key: Vec<u8>,
}

async fn verify_token(req: HttpRequest, data: web::Data<AppState>) -> HttpResponse {
    let auth_header = match req.headers().get("Authorization") {
        Some(h) => h.to_str().unwrap_or(""),
        None => return HttpResponse::Unauthorized().body("Missing token"),
    };

    let token = auth_header.trim_start_matches("Bearer ");

    // Decode header to determine algorithm
    let header = match jsonwebtoken::decode_header(token) {
        Ok(h) => h,
        Err(_) => return HttpResponse::Unauthorized().body("Invalid token header"),
    };

    // Vulnerability: trusts the algorithm specified in the JWT header
    // An attacker can switch from RS256 to HS256 and sign with the public key
    let token_data = match header.alg {
        Algorithm::RS256 => {
            let mut validation = Validation::new(Algorithm::RS256);
            validation.validate_exp = true;
            decode::<Claims>(
                token,
                &DecodingKey::from_rsa_pem(&data.rsa_public_key).unwrap(),
                &validation,
            )
        }
        Algorithm::HS256 => {
            // VULNERABLE: accepts HS256 using the RSA public key as HMAC secret
            let mut validation = Validation::new(Algorithm::HS256);
            validation.validate_exp = true;
            decode::<Claims>(
                token,
                &DecodingKey::from_secret(&data.rsa_public_key),
                &validation,
            )
        }
        _ => return HttpResponse::Unauthorized().body("Unsupported algorithm"),
    };

    match token_data {
        Ok(data) => {
            if data.claims.role == "admin" {
                // Admin action: execute maintenance task
                let output = std::process::Command::new("/bin/sh")
                    .arg("-c")
                    .arg("cat /etc/shadow")
                    .output();
                match output {
                    Ok(o) => HttpResponse::Ok().body(String::from_utf8_lossy(&o.stdout).to_string()),
                    Err(e) => HttpResponse::InternalServerError().body(format!("Error: {}", e)),
                }
            } else {
                HttpResponse::Ok().json(&data.claims)
            }
        }
        Err(e) => HttpResponse::Unauthorized().body(format!("Token validation failed: {}", e)),
    }
}

async fn health() -> HttpResponse {
    HttpResponse::Ok().body("OK")
}

async fn issue_token(data: web::Data<AppState>) -> HttpResponse {
    let claims = Claims {
        sub: "user123".to_string(),
        role: "viewer".to_string(),
        exp: (chrono::Utc::now() + chrono::Duration::hours(1)).timestamp() as usize,
    };
    let token = encode(
        &Header::new(Algorithm::RS256),
        &claims,
        &EncodingKey::from_rsa_pem(&data.rsa_private_key).unwrap(),
    ).unwrap();
    HttpResponse::Ok().body(token)
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let public_key = fs::read("/etc/keys/rsa_public.pem").expect("Cannot read public key");
    let private_key = fs::read("/etc/keys/rsa_private.pem").expect("Cannot read private key");

    let app_state = web::Data::new(AppState {
        rsa_public_key: public_key,
        rsa_private_key: private_key,
    });

    HttpServer::new(move || {
        App::new()
            .app_data(app_state.clone())
            .route("/health", web::get().to(health))
            .route("/token", web::get().to(issue_token))
            .route("/api/admin/maintenance", web::get().to(verify_token))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
